import { Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

interface ShimmerSweepProps {
  text: string;
  baseColor?: string;
  shineColor?: string;
  fontSize?: number;
  fontWeight?: number;
  speed?: number;
  className?: string;
}

function ShimmerSweepBase({
  text,
  baseColor = "#3f3f46",
  shineColor = "#fafafa",
  fontSize = 96,
  fontWeight = 700,
  speed = 1,
  className,
}: ShimmerSweepProps) {
  const frame = useCurrentFrame() * speed;
  const { durationInFrames } = useVideoConfig();

  const position = interpolate(
    frame,
    [0, durationInFrames * 0.8],
    [200, -100],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
  );

  const textStyle: React.CSSProperties = {
    fontSize,
    fontWeight,
    letterSpacing: "-0.03em",
    fontFamily:
      "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
    margin: 0,
    lineHeight: 1,
  };

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "white",
      }}
    >
      <div style={{ position: "relative", display: "inline-block" }}>
        <span style={{ ...textStyle, color: baseColor }}>{text}</span>
        <span
          className={className}
          style={{
            ...textStyle,
            position: "absolute",
            inset: 0,
            color: "transparent",
            backgroundClip: "text",
            WebkitBackgroundClip: "text",
            backgroundImage: `linear-gradient(110deg, transparent 30%, ${shineColor} 50%, transparent 70%)`,
            backgroundSize: "200% 100%",
            backgroundPosition: `${position}% 50%`,
          }}
        >
          {text}
        </span>
      </div>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  text: {
    type: "text-content",
    default: "Generating",
    description: "Text",
  },
  baseColor: {
    type: "color",
    default: "#3f3f46",
    description: "Base color",
  },
  shineColor: {
    type: "color",
    default: "#fafafa",
    description: "Shine color",
  },
  fontSize: {
    type: "number",
    min: 12,
    max: 200,
    step: 1,
    default: 96,
    description: "Font size",
    hiddenFromList: false,
  },
  fontWeight: {
    type: "enum",
    default: "700",
    variants: {
      "400": {},
      "500": {},
      "600": {},
      "700": {},
    },
    description: "Font weight",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["text","baseColor","shineColor","fontSize","fontWeight","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "Generating",
  baseColor: "#3f3f46",
  shineColor: "#fafafa",
  fontSize: 96,
  fontWeight: "700",
  speed: 1,
};

type ShimmerSweepElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShimmerSweepBase>;

const ShimmerSweepInner = forwardRef<
  HTMLDivElement,
  ShimmerSweepElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShimmerSweep>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShimmerSweepBase
          {...(componentProps as unknown as ComponentProps<typeof ShimmerSweepBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShimmerSweep = Interactive.withSchema({
  Component: ShimmerSweepInner,
  componentName: "<ShimmerSweep>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
